                    'libSystem.Security.Cryptography', 'libSystem.IO.Compression', 'libSystem.Net.Security']

# Collect all .NET-relevant image indices
dotnet_indices = set()
app_indices = set()
for i, img in enumerate(images):
    name = img.get('name', '')
    if name == 'SampleMAUI':
        app_indices.add(i)
    for lib in dotnet_lib_names:
        if lib in name:
            dotnet_indices.add(i)

print("=== APP BINARY ===")
for i in app_indices:
    img = images[i]
    print(f"  [{i}] {img['name']} base=0x{img['base']:x} uuid={img['uuid']} arch={img['arch']}")

print("\n=== .NET FRAMES IN ALL THREADS ===")
# Check all threads for .NET runtime frames
dotnet_frames_by_image = {}
for t_idx, thread in enumerate(crash['threads']):
    for f_idx, frame in enumerate(thread.get('frames', [])):
        img_idx = frame.get('imageIndex')
        if img_idx in dotnet_indices:
            img = images[img_idx]
            addr = img['base'] + frame.get('imageOffset', 0)
            key = img_idx
            if key not in dotnet_frames_by_image:
                dotnet_frames_by_image[key] = []
            dotnet_frames_by_image[key].append((t_idx, f_idx, addr))

# Also check lastExceptionBacktrace
leb = crash.get('lastExceptionBacktrace', [])
for f_idx, frame in enumerate(leb):
    img_idx = frame.get('imageIndex')
    if img_idx in dotnet_indices:
        img = images[img_idx]
        addr = img['base'] + frame.get('imageOffset', 0)
        key = img_idx
        if key not in dotnet_frames_by_image:
            dotnet_frames_by_image[key] = []
        dotnet_frames_by_image[key].append(('leb', f_idx, addr))

for img_idx, frames in sorted(dotnet_frames_by_image.items()):
    img = images[img_idx]
    print(f"\n  {img['name']} (base=0x{img['base']:x}, uuid={img['uuid']})")
    addrs = set()
    for t, f, addr in frames:
        addrs.add(addr)
        print(f"    thread={t} frame={f} addr=0x{addr:x}")

# Now for the app binary - check for bridge functions
print("\n\n=== APP BINARY (SampleMAUI) FRAMES (for bridge functions) ===")
app_frames_by_image = {}
for t_idx, thread in enumerate(crash['threads']):
    for f_idx, frame in enumerate(thread.get('frames', [])):
        img_idx = frame.get('imageIndex')
        if img_idx in app_indices:
            img = images[img_idx]
            addr = img['base'] + frame.get('imageOffset', 0)
            if img_idx not in app_frames_by_image:
                app_frames_by_image[img_idx] = []
            app_frames_by_image[img_idx].append((t_idx, f_idx, addr))

for f_idx, frame in enumerate(leb):
    img_idx = frame.get('imageIndex')
    if img_idx in app_indices:
        img = images[img_idx]
        addr = img['base'] + frame.get('imageOffset', 0)
        if img_idx not in app_frames_by_image:
            app_frames_by_image[img_idx] = []
        app_frames_by_image[img_idx].append(('leb', f_idx, addr))

for img_idx, frames in sorted(app_frames_by_image.items()):
    img = images[img_idx]
    print(f"\n  {img['name']} (base=0x{img['base']:x}, uuid={img['uuid']})")
    for t, f, addr in frames[:20]:
        print(f"    thread={t} frame={f} addr=0x{addr:x}")

# Generate atos commands
