for t_idx, thread in enumerate(crash['threads']):
    for frame in thread.get('frames', []):
        if frame.get('imageIndex') == 7:
            addr = images[7]['base'] + frame.get('imageOffset', 0)
            coreclr_addrs.add(addr)
for frame in leb:
